parameters.jsCode:
const body = $input.first().json.body;
const required = ['event_name', 'shifts'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.shifts) || body.shifts.length === 0) return [{ json: { valid: false, error: 'shifts must be a non-empty array' } }];
return [{ json: {
  valid: true,
  eventName: body.event_name.trim(),
  eventDescription: (body.event_description || '').slice(0, 400),
  shifts: body.shifts.map(s => ({
    shiftId: s.shift_id || `S-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,
    date: s.date,
    startTime: s.start_time,
    endTime: s.end_time,
    role: s.role || 'general',
    volunteersNeeded: parseInt(s.volunteers_needed) || 1,
    requiredSkills: Array.isArray(s.required_skills) ? s.required_skills : (s.required_skills || '').split(',').map(x=>x.trim()).filter(Boolean),
    location: s.location || '',
    notes: s.notes || ''
  })),
  notifyVolunteers: body.notify_volunteers !== false,
  coordinatorEmail: body.coordinator_email || '',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const volunteers = $('Load All Availability').all().map(r => r.json).filter(r => r.volunteer_name);
const schedReq = $('Validate Schedule Request').first().json;

// Parse availability
const parsed = volunteers.map(v => ({
  id: v.volunteer_id,
  name: v.volunteer_name,
  email: v.volunteer_email,
  role: v.role || 'general',
  skills: (v.skills || '').split(',').map(s => s.trim()).filter(Boolean),
  availableDates: (v.available_dates || '').split(',').map(d => d.trim()).filter(Boolean),
  preferredShifts: (v.preferred_shifts || '').split(',').map(s => s.trim()).filter(Boolean),
  maxShifts: parseInt(v.max_shifts_per_week) || 3,
  notes: v.notes || '',
  assignedCount: 0
}));

// Match volunteers to shifts
const assignments = [];
const unfilledShifts = [];
const shiftAssignments = {};

for (const shift of schedReq.shifts) {
  const eligible = parsed.filter(v => {
    const dateMatch = v.availableDates.some(d => d.includes(shift.date) || shift.date.includes(d));
    const roleMatch = !shift.role || shift.role === 'general' || v.role === shift.role || v.role === 'general';
    const skillsMatch = shift.requiredSkills.length === 0 || shift.requiredSkills.every(s => v.skills.map(sk=>sk.toLowerCase()).includes(s.toLowerCase()));
    const notOverloaded = v.assignedCount < v.maxShifts;
    return dateMatch && roleMatch && skillsMatch && notOverloaded;
  });

  const selected = eligible.slice(0, shift.volunteersNeeded);
  selected.forEach(v => { v.assignedCount++; });

  shiftAssignments[shift.shiftId] = selected.map(v => ({ id: v.id, name: v.name, email: v.email, role: v.role }));

  assignments.push({
    shift,
    assigned: selected.map(v => ({ id: v.id, name: v.name, email: v.email, role: v.role })),
    filled: selected.length,
    needed: shift.volunteersNeeded,
    fullyStaffed: selected.length >= shift.volunteersNeeded
  });

  if (selected.length < shift.volunteersNeeded) {
    unfilledShifts.push({ ...shift, filled: selected.length, needed: shift.volunteersNeeded });
  }
}

const totalVolunteers = parsed.length;
const assignedVolunteers = parsed.filter(v => v.assignedCount > 0).length;
const fullyStaffedCount = assignments.filter(a => a.fullyStaffed).length;

return [{ json: {
  schedReq,
  assignments,
  unfilledShifts,
  stats: { totalVolunteers, assignedVolunteers, totalShifts: schedReq.shifts.length, fullyStaffed: fullyStaffedCount },
  volunteerList: parsed
} }];

