parameters.jsCode:
const note = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Match Volunteers to Shifts').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const shiftRows = d.assignments.map(a => {
  const names = a.assigned.map(v => esc(v.name)).join(', ') || '<span style="color:#dc2626;font-weight:700">UNFILLED</span>';
  const statusColor = a.fullyStaffed ? '#16a34a' : a.filled > 0 ? '#d97706' : '#dc2626';
  const statusLabel = a.fullyStaffed ? 'Full' : a.filled > 0 ? `${a.filled}/${a.needed}` : 'Empty';
  return `<tr style="border-bottom:1px solid #f3f4f6">
    <td style="padding:9px 12px;font-size:13px;font-weight:600">${esc(a.shift.date)}</td>
    <td style="padding:9px 12px;font-size:13px">${esc(a.shift.startTime)}–${esc(a.shift.endTime)}</td>
    <td style="padding:9px 12px;font-size:13px">${esc(a.shift.role)}</td>
    <td style="padding:9px 12px;font-size:13px">${names}</td>
    <td style="padding:9px 12px;text-align:center"><span style="background:${statusColor}22;color:${statusColor};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px">${statusLabel}</span></td>
  </tr>`;
}).join('');

const noteHtml = note.replace(/\n/g,'<br>');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1e3a5f;color:#fff;padding:18px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#7b9ec9;margin-bottom:5px">Volunteer Schedule</div>
    <div style="font-size:19px;font-weight:700">${esc(d.schedReq.eventName)}</div>
    <div style="font-size:13px;color:#7b9ec9;margin-top:3px">${d.stats.totalShifts} shifts · ${d.stats.fullyStaffed} fully staffed · ${d.unfilledShifts.length} unfilled · ${d.stats.assignedVolunteers}/${d.stats.totalVolunteers} volunteers assigned</div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Coordinator summary</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${noteHtml}</p>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#f9fafb;font-size:11px;text-transform:uppercase;color:#9ca3af">
        <th style="padding:8px 12px;text-align:left">Date</th>
        <th style="padding:8px 12px;text-align:left">Time</th>
        <th style="padding:8px 12px;text-align:left">Role</th>
        <th style="padding:8px 12px;text-align:left">Volunteers</th>
        <th style="padding:8px 12px;text-align:center">Status</th>
      </tr></thead>
      <tbody>${shiftRows}</tbody>
    </table>
  </div>
  <div style="background:#1e3a5f;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Volunteer Scheduler · ${esc(d.schedReq.eventName)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: d.schedReq.replyEmail, coordinatorEmail: d.schedReq.coordinatorEmail, eventName: d.schedReq.eventName, unfilledCount: d.unfilledShifts.length, stats: d.stats, assignments: d.assignments, volunteerList: d.volunteerList, notifyVolunteers: d.schedReq.notifyVolunteers } }];
